contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        // build an order whose maker is this test contract (msg.sender for all calls on c)
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: true,
            baseAsset: address(c),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // read-only: order hash and opposite order hash are always distinct
        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        assert(orderHash != oppositeHash);

        // state-changing call at top level: the maker cancels its own order
        c.cancel(order);

        // general rule: after cancel by maker, the order hash is marked cancelled
        assert(c.cancelledOrders(orderHash));
    }

    receive() external payable {}
}

