contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newFee) public payable {
        // precondition: attempt a valid fee value and an invalid one
        uint256 testFee = newFee % 40; // spans 0..39, mixing valid (<30) and invalid (>=30)
        bool reverted;
        uint256 afterFee;
        if (testFee < 30) {
            c.setFee(testFee);
            reverted = false;
            afterFee = c.fee();
        } else {
            try c.setFee(testFee) { reverted = false; } catch { reverted = true; }
            afterFee = c.fee();
        }
        assert(
            (testFee < 30 ? (!reverted && afterFee == testFee) : reverted)
        );
    }
    receive() external payable {}
}

