contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string memory base, uint256 tokenId) public {
        c.setBaseURI(base);
        string memory uri = c.tokenURI(tokenId);
        // expected = base ++ decimal(tokenId)
        uint256 tmp = tokenId;
        uint256 digits = 0;
        if (tmp == 0) digits = 1;
        while (tmp != 0) { digits++; tmp /= 10; }
        bytes memory baseB = bytes(base);
        bytes memory expected = new bytes(baseB.length + digits);
        for (uint256 i = 0; i < baseB.length; i++) expected[i] = baseB[i];
        uint256 v = tokenId;
        uint256 idx = baseB.length + digits;
        if (v == 0) { expected[baseB.length] = bytes1(uint8(48)); }
        while (v != 0) {
            idx--;
            expected[idx] = bytes1(uint8(48 + (v % 10)));
            v /= 10;
        }
        assert(keccak256(bytes(uri)) == keccak256(expected));
    }
    receive() external payable {}
}

