contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens,
        C.ERC20Asset[] calldata erc20Assets,
        C.ERC721Asset[] calldata erc721Assets,
        bool byMaker
    ) public {
        address maker = byMaker ? address(this) : address(0x1234);
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bool flagBefore = c.cancelledOrders(orderHash);

        bool reverted;
        if (byMaker) {
            c.cancel(order);
            reverted = false;
        } else {
            try c.cancel(order) { reverted = false; }
            catch { reverted = true; }
        }

        bool flagAfter = c.cancelledOrders(orderHash);

        assert(
            (byMaker && !reverted && !flagBefore && flagAfter) ||
            (!byMaker && reverted && flagBefore == flagAfter)
        );
    }

    receive() external payable {}
}

